<script setup lang="ts">
import {seasonLabel} from '../../../../packages/shared/src/learning';
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';import {get,request} from '../../../../packages/shared/src/client';import {useOperations} from '../../../../packages/shared/src/operations';import {useTask,type Row} from '../../../../packages/shared/src/ui';import Status from '../../../../packages/shared/src/Status.vue';
import {useRoute,useRouter} from 'vue-router';
const route=useRoute(),router=useRouter();
const task=useTask(),ops=useOperations(),seasons=ref<Row[]>([]),month=ref(String(route.query.month||'')),board=ref<Row>({}),signs=ref<Row>({}),points=ref<Row>({}),achievements=ref<Row[]>([]),rewards=ref<Row[]>([]),page=ref(1),pointPage=ref(1),tab=ref('board'),creditPending=ref(false),creditHint=ref('');
let disposed=false,creditTimer:ReturnType<typeof setTimeout>|undefined,finishWait:(()=>void)|undefined;const creditAbort=new AbortController();
onBeforeUnmount(()=>{disposed=true;creditAbort.abort();if(creditTimer)clearTimeout(creditTimer);finishWait?.();});
function signedToday(rows:Row[]){const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());return rows.some(p=>Number(p.type)===2&&String(p.occurredAt).slice(0,10)===today);}
async function awaitCredit(){creditPending.value=true;creditHint.value='积分正在到账，排行榜会自动刷新。';try{for(const delay of [500,1000,2000,3000,3000]){await new Promise<void>(resolve=>{finishWait=resolve;creditTimer=setTimeout(resolve,delay);});if(disposed)return;const recent=await request<Row>('/learning-hub/points?pageNo=1&pageSize=20',{signal:creditAbort.signal});if(!signedToday(recent.list||[]))continue;const selectedMonth=month.value,selectedPage=pointPage.value,selectedBoardPage=page.value;const [pp,bb]=await Promise.all([request<Row>('/learning-hub/points?pageNo='+selectedPage+'&pageSize=20',{signal:creditAbort.signal}),request<Row>('/learning-hub/board?month='+selectedMonth+'&pageNo='+selectedBoardPage+'&pageSize=20',{signal:creditAbort.signal})]);if(disposed)return;if(pointPage.value===selectedPage)points.value=pp;if(month.value===selectedMonth&&page.value===selectedBoardPage)board.value=bb;creditHint.value='签到积分已到账';return;}creditHint.value='积分仍在处理中，可稍后刷新查询。';}catch{if(!disposed)creditHint.value='暂时无法刷新积分，可稍后重新查询。';}finally{if(!disposed)creditPending.value=false;}}
const rewardStatus=(value:unknown)=>({PENDING:'发放中',FAILED:'待处理',FULFILLED:'已发放'}[String(value)]||'待核对');
const signedDays=computed(()=>new Set((signs.value.signRecords||[]).flatMap((value:number,index:number)=>Number(value)===1?[index+1]:[])));
const days=computed(()=>Array.from({length:Number(signs.value.daysInMonth||new Date(new Date().getFullYear(),new Date().getMonth()+1,0).getDate())},(_,i)=>i+1));
const leading=computed(()=>{const raw=String(signs.value.month||new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit'}).format(new Date())).replace('-','');return (new Date(Number(raw.slice(0,4)),Number(raw.slice(4,6))-1,1).getDay()+6)%7;});
async function loadBoard(){void router.replace({query:{month:month.value}});await task.run(async()=>{board.value=await get<Row>('/learning-hub/board?month='+month.value+'&pageNo='+page.value+'&pageSize=20');});}
async function loadPoints(){await task.run(async()=>{points.value=await get<Row>('/learning-hub/points?pageNo='+pointPage.value+'&pageSize=20');});}
async function load(){await task.run(async()=>{const [ss,si,pp,aa,rr]=await Promise.all([get<Row[]>('/learning-hub/seasons'),get<Row>('/sign-ins'),get<Row>('/learning-hub/points?pageNo='+pointPage.value+'&pageSize=20'),get<Row>('/learning-hub/achievements'),get<Row>('/learning-hub/rewards')]);seasons.value=ss;month.value=month.value||String(si.month||new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit'}).format(new Date()).replace('-',''));signs.value=si;points.value=pp;achievements.value=aa.list||[];rewards.value=rr.list||[];board.value=await get<Row>('/learning-hub/board?month='+month.value+'&pageNo='+page.value+'&pageSize=20');});}
async function sign(){const result=await task.run(()=>ops.begin('learning','每日签到','/sign-ins',undefined));if(result?.status==='SUCCEEDED'){await load();task.message.value='签到成功';if(!signedToday(points.value.list||[]))void awaitCredit();else creditHint.value='签到积分已到账';}else if(result)task.message.value='签到处理中，可在操作记录中继续查询';}
onMounted(load);
</script><template><section class="points-page"><div class="section-heading"><div><h1>积分与签到</h1><p>每一次完成，都留下进步的记录。</p></div><el-button @click="load" :disabled="task.busy.value">刷新积分</el-button></div><Status :busy="task.busy.value" :error="task.error.value" :message="task.message.value"/><p v-if="creditHint" class="credit-pending" :role="creditPending?'status':undefined">{{creditHint}}</p><div class="points-overview"><section class="card sign-panel"><div class="section-heading"><h2>本月签到</h2><el-button type="primary" @click="sign" :disabled="task.busy.value||signs.todaySigned">{{signs.todaySigned?'今日已签到':'今日签到'}}</el-button></div><p>连续签到 {{signs.signDays||0}} 天</p><div class="sign-calendar" aria-label="当月签到日历"><span v-for="day in ['一','二','三','四','五','六','日']" :key="day" class="calendar-weekday">{{day}}</span><span v-for="n in leading" :key="'blank'+n"/><span v-for="day in days" :key="day" :class="{signed:signedDays.has(day)}" :aria-label="day+'日'+(signedDays.has(day)?'已签到':'未签到')">{{day}}<small v-if="signedDays.has(day)">已签</small></span></div><p class="muted">签到及连续签到奖励按规则到账。</p></section><section class="card season-panel"><h2>我的赛季</h2><p>{{seasons.find(s=>s.month===month)?.name||'当月赛季'}} · {{seasonLabel(board.status,board.month||month)}}</p><strong class="season-rank">{{board.myRank?board.myRank:'暂未上榜'}}</strong><p>赛季积分 {{board.myPoints||0}}</p><p v-if="Number(board.myRank)>1">距上一名 {{board.gapToPrevious}} 分</p><p>首次完成小节 +10 分，每日上限 50 分；教师采纳回答 +5 分，每日上限 20 分。</p><p class="muted">同分按达到积分的时间、用户编号排序。次月 2 日起结算，最终成绩以历史快照为准。</p></section></div><el-tabs v-model="tab"><el-tab-pane label="积分排行榜" name="board"/><el-tab-pane label="积分明细" name="points"/><el-tab-pane label="我的成就" name="achievements"/><el-tab-pane label="赛季奖励" name="rewards"/></el-tabs><section class="card"><template v-if="tab==='board'"><div class="section-heading"><h2>积分排行榜</h2><el-select v-model="month" aria-label="选择赛季" @change="page=1;loadBoard()"><el-option v-for="season in seasons" :key="season.month" :value="season.month" :label="season.name+' · '+seasonLabel(season.status,season.month)"/></el-select></div><p v-if="board.settledAt">最终结算时间 {{board.settledAt}}</p><el-table :data="board.list||[]" empty-text="本赛季暂时无人上榜"><el-table-column prop="rank" label="排名" width="100"/><el-table-column prop="name" label="同学"/><el-table-column prop="points" label="积分"/></el-table><el-pagination v-if="board.total>20" v-model:current-page="page" :total="Number(board.total)" :page-size="20" layout="prev,pager,next" @current-change="loadBoard"/></template><template v-else-if="tab==='points'"><h2>积分明细</h2><el-table :data="points.list||[]" empty-text="还没有积分记录"><el-table-column prop="typeName" label="积分来源"/><el-table-column prop="points" label="积分"/><el-table-column prop="occurredAt" label="完成时间" min-width="180"/><el-table-column label="到账状态"><template #default="{row}">{{row.late?'待核对':row.creditedAt?'已到账':'处理中'}}</template></el-table-column></el-table><el-pagination v-if="points.total>20" v-model:current-page="pointPage" :total="Number(points.total)" :page-size="20" layout="prev,pager,next" @current-change="loadPoints"/></template><template v-else-if="tab==='achievements'"><h2>我的成就</h2><div class="achievement-list"><article v-for="item in achievements" :key="item.code+item.seasonMonth"><h3>{{item.name}}</h3><p>{{item.seasonMonth?item.seasonMonth+' 赛季':'学习成就'}}</p><small>{{item.awardedAt}}</small></article></div><el-empty v-if="!achievements.length" description="完成学习与考试，积累你的第一枚成就"/></template><template v-else><h2>赛季奖励</h2><el-table :data="rewards" empty-text="暂无赛季奖励"><el-table-column prop="seasonMonth" label="赛季"/><el-table-column prop="rankNo" label="名次"/><el-table-column label="发放状态"><template #default="{row}">{{rewardStatus(row.status)}}</template></el-table-column><el-table-column prop="lastError" label="说明"/></el-table><RouterLink to="/coupons">查看我的优惠券 →</RouterLink></template></section></section></template>